			}
		},
	}
	upCmd = &cobra.Command{
		Use:   "up [no options!]",
		Short: "migrate up",
		Run: func(cmd *cobra.Command, args []string) {
			var err error
			defer func() {
				if err != nil {
					zap.L().Fatal("", zap.Error(err))
				}
			}()

			db, err := migrationInit()
			if err != nil {
				return
			}
			defer db.Close()
			up(db)
		},
	}
	downCmd = &cobra.Command{
		Use:   "down [no options!]",
		Short: "migrate down",
		Run: func(cmd *cobra.Command, args []string) {
			var err error
			defer func() {
				if err != nil {
					zap.L().Fatal("", zap.Error(err))
				}
			}()

			db, err := migrationInit()
			if err != nil {
				return
			}
			defer db.Close()
			down(db)
		},
	}
	migrations = &migrate.MemoryMigrationSource{
		Migrations: []*migrate.Migration{
			&migrate.Migration{
				Id: "1",
				Up: []string{
					`CREATE TABLE users(
					uid           uuid   PRIMARY KEY  NOT NULL,
					email          text    NOT NULL,
					password        text   NOT NULL,
					first_name      text,
					last_name 		text,
					created_at  TIMESTAMP
