	"strings"

	"auth/internal/storage/pg"

	"github.com/asaskevich/govalidator"
	"github.com/spf13/viper"
)

var ErrConfig = errors.New("Wrong config")

type Service struct {
	API   API
	DB    *pg.Config
	Debug bool
}

type API struct {
	Port               string `valid:"required"`
	MaxRequestBodySize int    `valid:"required"`
	TTL                int64  `valid:"required"`
}

func Read() (*Service, error) {
	sc := &Service{}
	svc := viper.New()
	svc.AutomaticEnv()

	svc.SetEnvPrefix("AUTH")
	svc.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	//----------------
	svc.BindEnv("Api.Port")
	svc.BindEnv("Api.Maxrequestbodysize")
	svc.BindEnv("Api.TTL")
	//----------
	svc.BindEnv("DB.Host")
	svc.BindEnv("DB.Port")
	svc.BindEnv("DB.User")
	svc.BindEnv("DB.Password")
	svc.BindEnv("DB.DatabaseName")
	svc.BindEnv("DB.SSL")
	//------------
	svc.BindEnv("Debug")
	//--------------
	err := svc.Unmarshal(sc)
	if err != nil {
		return nil, err
	}
	if _, err = govalidator.ValidateStruct(sc); err != nil {
		return nil, err
	}

	return sc, nil
}

package http

import (
	"auth/internal/server/transport/http/handlers"
	"auth/internal/server/transport/http/middleware"

	"github.com/buaazp/fasthttprouter"
	"github.com/valyala/fasthttp"
)

const (
	Root = "/api/v1"
)

type Server struct {
	HTTPServer *fasthttp.Server
	router     *fasthttprouter.Router
	Handlers   *handlers.Handlers
}

func NewServer(hs *handlers.Handlers, rs int) (*Server, error) {

	s := &Server{
		router:   &fasthttprouter.Router{},
		Handlers: hs,
	}
	h := s.router.Handler
	s.HTTPServer = newHTTPServer(h, rs)
	return s, nil
}

func newHTTPServer(h fasthttp.RequestHandler, rs int) *fasthttp.Server {
	return &fasthttp.Server{
		Handler:            h,
		MaxRequestBodySize: rs,
	}

}

func (s *Server) Run(port string) error {
	return s.HTTPServer.ListenAndServe(":" + port)
}

func (s *Server) RoutesInit() {
	s.router.POST(Root+"/users", middleware.LogRequest(s.Handlers.Registration))
	s.router.POST(Root+"/sessions", middleware.LogRequest(s.Handlers.Session))
}

package middleware

import (
	"time"

	"github.com/valyala/fasthttp"
	"go.uber.org/zap"
)

func LogRequest(h fasthttp.RequestHandler) fasthttp.RequestHandler {
	return func(ctx *fasthttp.RequestCtx) {
		start := time.Now()
		h(ctx)
		addr := ctx.RemoteIP().String()
		zap.L().Debug("http request", zap.String("method", string(ctx.Method())), zap.String("path", string(ctx.RequestURI())), zap.String("RemoteIP", addr), zap.Duration("duration", time.Since(start)))
	}
}

package pg

import (
	"fmt"
	"time"

	"github.com/jmoiron/sqlx"
	_ "github.com/lib/pq"
	"go.uber.org/zap"
)

const (
	maxRetry = 10
	ttlRetry = 1 * time.Second
)

type Config struct {
	Host         string `valid:"required"`
	Port         string `valid:"required"`
	User         string `valid:"required"`
	Password     string `valid:"required"`
	DatabaseName string
	Schema       string
	SSL          string
	MaxIdleConns int
	MaxOpenConns int
}

type Database struct {
	Client *sqlx.DB
	log    *zap.Logger
}

func New(log *zap.Logger) *Database {
	return &Database{log: log}
}
func (d *Database) Connect(dbc *Config) error {
	args := fmt.Sprintf(
		"REDACTED",
		dbc.SSL,
		dbc.Host,
		dbc.Port,
		dbc.User,
		dbc.Password,
		dbc.DatabaseName,
	)

	var (
		conn *sqlx.DB
		err  error
	)
	retry := 1
	for retry < maxRetry {
		conn, err = sqlx.Connect("postgres", args)
		if err != nil {
			d.log.Error("", zap.Int("#retrying:", retry), zap.String("second:", ttlRetry.String()))
			retry++
			time.Sleep(ttlRetry)
			continue
		}
		break
	}
	if conn != nil {
		if dbc.MaxIdleConns > 0 {
			conn.SetMaxIdleConns(dbc.MaxIdleConns)
		}
		if dbc.MaxOpenConns > 0 {
			conn.SetMaxOpenConns(dbc.MaxOpenConns)
		}
		d.Client = conn
	}

	return err
}

