	defer undo()

	cfg, err := config.Read()
	if err != nil {
		log.Fatal("", zap.Error(err))
	}
	if cfg.Debug {
		zap.L().Sync()
		log = zap.NewNop()
		zap.ReplaceGlobals(log)
	}
	db := pg.New(log)
	if err := db.Connect(cfg.DB); err != nil {
		log.Fatal("", zap.Error(err))
	}
